package com.cyberpath.learning;
import android.app.*;import android.appwidget.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import org.json.*;import java.time.*;import java.io.*;
public final class NativeOfflineSmoke {
 private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 public static void rules(Bundle report)throws Exception{JSONArray fixtures=new JSONArray(NativeReminderCases.JSON);for(int i=0;i<fixtures.length();i++){JSONObject f=fixtures.getJSONObject(i),row=f.getJSONObject("row");if(f.optBoolean("expectedError")){try{ReminderActions.nextDay(row,Instant.parse(f.getString("now")));throw new AssertionError("Impossible workday rule was accepted");}catch(IllegalArgumentException expected){}continue;}require(f.getString("expected").equals(ReminderActions.nextDay(row,Instant.parse(f.getString("now")))),"Native repeat differs from JS: "+i+" "+row);JSONObject w=new JSONObject().put("courses",new JSONObject().put("untouched",42)).put("learning",new JSONObject().put("organizer",new JSONObject().put("items",new JSONArray().put(new JSONObject(row.toString())))));String before=w.toString();JSONObject receipt=ReminderActions.apply(w,row.getString("id"),"done",ReminderActions.identity(row),Instant.parse(f.getString("now")));require(w.getJSONObject("courses").getInt("untouched")==42,"Reminder changed Study");try{ReminderActions.apply(w,row.getString("id"),"done",ReminderActions.identity(row),Instant.now());throw new AssertionError("Double action was accepted");}catch(IllegalStateException expected){}ReminderActions.undo(w,receipt);require(new JSONObject(before).getJSONObject("learning").toString().equals(w.getJSONObject("learning").toString()),"Undo changed reminder fields");}report.putInt("native_js_recurrence_parity_cases",fixtures.length());report.putBoolean("native_reminder_done_undo_and_double_action_guards",true);}
 public static void components(Instrumentation test,MainActivity activity,Bundle report)throws Exception{
  Context c=test.getTargetContext();ProviderInfo share=c.getPackageManager().getProviderInfo(new ComponentName(c,CourseShareProvider.class),0);require(!share.exported&&share.grantUriPermissions,"Course export provider is not narrow");String raw="{\"format\":\"lw-learning-studio\",\"version\":2,\"kind\":\"course\",\"data\":{}}";Uri uri=CourseShareProvider.prepare(c,raw,"Practice.course.lw");try(InputStream in=c.getContentResolver().openInputStream(uri)){require(new String(AppFiles.readBounded(in,10000),java.nio.charset.StandardCharsets.UTF_8).equals(raw),"Shared course bytes changed");}try{c.getContentResolver().openFileDescriptor(uri,"w");throw new AssertionError("Shared course is writable");}catch(FileNotFoundException expected){}try{CourseShareProvider.prepare(c,"{\"workspace\":{}}","Private.lw");throw new AssertionError("Workspace shared as course");}catch(IOException expected){}try{c.getContentResolver().openInputStream(Uri.parse("content://"+c.getPackageName()+".course-share/../../studio-workspace.json"));throw new AssertionError("Shared provider escaped cache");}catch(FileNotFoundException expected){}report.putBoolean("nearby_course_provider_readonly_bytes_and_private_guards",true);
  ActivityInfo widget=c.getPackageManager().getReceiverInfo(new ComponentName(c,PersonalReminderWidget.class),PackageManager.GET_META_DATA);require(!widget.exported&&widget.metaData.getInt("android.appwidget.provider")!=0,"Reminder widget registration missing");ServiceInfo audio=c.getPackageManager().getServiceInfo(new ComponentName(c,LocalAudioService.class),0);require(!audio.exported&&(audio.getForegroundServiceType()&ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK)!=0,"Audio service declaration missing");report.putBoolean("separate_reminder_widget_and_media_service_registration",true);
  MainActivity.NativeBridge bridge=activity.new NativeBridge();String profile=bridge.getActiveProfile();byte[] wav=new byte[44+16000*2*4];java.nio.ByteBuffer b=java.nio.ByteBuffer.wrap(wav).order(java.nio.ByteOrder.LITTLE_ENDIAN);b.put("RIFF".getBytes()).putInt(wav.length-8).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(wav.length-44);for(int n=0;n<64000;n++)b.putShort((short)(Math.sin(n*Math.PI*440/8000)*1000));JSONObject prepared=new JSONObject(bridge.prepareLocalAudio("data:audio/wav;base64,"+android.util.Base64.encodeToString(wav,android.util.Base64.NO_WRAP),"Native listening fixture",profile));require(prepared.optDouble("duration")>3.9,"Local audio metadata missing");JSONObject request=new JSONObject().put("operation","load").put("profile",profile).put("token",prepared.getString("token")).put("title","Native listening fixture").put("loop",true).put("start",0.5).put("end",2.5).put("seek",0.5);require(new JSONObject(bridge.localAudioCommand(request.toString())).getBoolean("ok"),"Audio load command failed");for(int n=0;n<200&&!LocalAudioService.status(profile).optBoolean("playing");n++)SystemClock.sleep(50);require(LocalAudioService.status(profile).optBoolean("playing"),"Native local audio never played: "+LocalAudioService.status(profile));require(LocalAudioService.status("foreign").optDouble("duration")==0,"Audio metadata leaked to another profile");request.put("operation","pause");bridge.localAudioCommand(request.toString());for(int n=0;n<30&&LocalAudioService.status(profile).optBoolean("playing");n++)SystemClock.sleep(50);require(!LocalAudioService.status(profile).optBoolean("playing"),"Notification/session pause failed");request.put("operation","seek").put("seek",1.25);bridge.localAudioCommand(request.toString());for(int n=0;n<100&&Math.abs(LocalAudioService.status(profile).optDouble("seconds")-1.25)>=.2;n++)SystemClock.sleep(50);require(Math.abs(LocalAudioService.status(profile).optDouble("seconds")-1.25)<.2&&!LocalAudioService.status(profile).optBoolean("playing"),"Native paused seek failed");request.put("operation","stop");bridge.localAudioCommand(request.toString());report.putBoolean("native_local_audio_prepare_play_pause_seek_stop",true);NativeFacadeSmoke.run(test,activity,report,"data:audio/wav;base64,"+android.util.Base64.encodeToString(wav,android.util.Base64.NO_WRAP));
 }
 public static void transactions(Context c,MainActivity.NativeBridge bridge,String profile,Bundle report)throws Exception{
  JSONObject w=new JSONObject(bridge.getState(profile)),r=w.getJSONObject("learning").getJSONObject("organizer").getJSONArray("items").getJSONObject(0);String id=r.getString("id");String study=w.getJSONObject("courses").toString();Intent action=new Intent(c,ReminderActions.class).setAction(ReminderActions.ACTION).putExtra("profile",profile).putExtra("id",id).putExtra("operation","done").putExtra("identity",ReminderActions.identity(r));long revision=w.getLong("revision");require(ReminderActions.transact(c,action),"Reminder transaction failed");w=new JSONObject(bridge.getState(profile));require(w.getLong("revision")==revision+1,"Native action did not increment revision");require(w.getJSONObject("learning").getJSONObject("organizer").getJSONArray("items").getJSONObject(0).getString("status").equals("completed"),"Native action did not complete");require(study.equals(w.getJSONObject("courses").toString()),"Notification action changed Study");try{ReminderActions.transact(c,action);throw new AssertionError("Stale action repeated");}catch(IllegalStateException expected){}JSONObject receipt=new JSONObject(NativeServices.prefs(c).getString("reminderUndo","{}"));require(ReminderActions.transact(c,new Intent().putExtra("profile",profile).putExtra("operation","undo").putExtra("identity",receipt.getString("after"))),"Native Undo failed");require(new JSONObject(bridge.getState(profile)).getJSONObject("learning").getJSONObject("organizer").getJSONArray("items").getJSONObject(0).getString("status").equals("pending"),"Undo did not reopen reminder");JSONObject pendingRow=new JSONObject(bridge.getState(profile)).getJSONObject("learning").getJSONObject("organizer").getJSONArray("items").getJSONObject(0);ReminderActions.pending(c,profile,pendingRow,"snooze").send();JSONObject afterSnooze=null;for(int n=0;n<100;n++){afterSnooze=new JSONObject(bridge.getState(profile)).getJSONObject("learning").getJSONObject("organizer").getJSONArray("items").getJSONObject(0);if(afterSnooze.optInt("editRevision")>pendingRow.optInt("editRevision"))break;SystemClock.sleep(50);}require(afterSnooze.optInt("editRevision")==pendingRow.optInt("editRevision")+1,"Snooze PendingIntent did not reach its receiver");JSONObject snoozeReceipt=new JSONObject(NativeServices.prefs(c).getString("reminderUndo","{}"));require(ReminderActions.transact(c,new Intent().putExtra("profile",profile).putExtra("operation","undo").putExtra("identity",snoozeReceipt.getString("after"))),"Snooze Undo failed");report.putBoolean("real_snooze_pending_intent_receiver_and_undo",true);c.getSharedPreferences("lw-app-lock",Context.MODE_PRIVATE).edit().putBoolean("enabled",true).commit();try{ReminderActions.transact(c,action);throw new AssertionError("Locked app accepted action");}catch(IllegalStateException expected){}finally{c.getSharedPreferences("lw-app-lock",Context.MODE_PRIVATE).edit().putBoolean("enabled",false).commit();}report.putBoolean("notification_widget_transactions_revision_profile_lock_and_undo",true);
  String key="asset-cleanup-fixture";LocalLibrary.put(c,key,"{\"id\":\"cleanup-fixture\",\"dataURL\":\"data:text/plain;base64,dGVzdA==\"}");LocalLibrary.deleteUnused(c,key);require(LocalLibrary.get(c,key).isEmpty(),"Physical unused file remains");try{LocalLibrary.deleteUnused(c,"journal-record");throw new AssertionError("Journal deleted by cleanup");}catch(IOException expected){}report.putBoolean("physical_file_cleanup_boundary",true);bridge.configureWatchMirroring(false,profile);require(!bridge.getWatchMirroring(),"Watch preference did not save");bridge.configureWatchMirroring(true,profile);require(bridge.getWatchMirroring(),"Watch preference did not restore");report.putBoolean("paired_watch_notification_preference",true);
 }
}
